// Move Zeroes - Move all zeroes to the end in-place
var array = AnimatedArray<Int>()
array.append(0)
array.append(1)
array.append(0)
array.append(3)
array.append(12)

func moveZeroes(arr: inout AnimatedArray<Int>) {
    var lastNonZeroFoundAt = 0
    for i in 0..<arr.count {
        if let current = arr.at(i), current != 0 {
            if let val = arr.remove(at: i) {
                arr.insert(val, at: lastNonZeroFoundAt)
            }
            lastNonZeroFoundAt += 1
        }
    }
}

moveZeroes(arr: &array)
